from abc import abstractmethod, ABCMeta


class ParserBase(object):
    def __init__(self, raw_output):
        super(ParserBase, self).__init__()
        self.raw_output = raw_output


class CommonStatCommandParser(ParserBase):
    __metaclass__ = ABCMeta

    def __init__(self, raw_output):
        super(CommonStatCommandParser, self).__init__(raw_output)
        self._tx_per_antenna = {}
        self._tx_list = []
        self._channel_status = []
        self._frequency = []
        self._channel_type = []
        self._bandwidth = []
        self._resource = []

    @abstractmethod
    def _prepare_data(self):
        """Parse raw radio output and setup all private variable"""

    def _parse_carrier_by_tx(self):
        carrier_data = {}
        for index, value in enumerate(self._tx_list):
            carrier_data.setdefault(
                self._tx_list[index],
                {
                    "state": self._channel_status[index],
                    "frequency": self._frequency[index],
                    "type": self._channel_type[index],
                    "bandwidth": self._bandwidth[index],
                },
            )
        return carrier_data

    def parse_carrier_by_antenna(self):
        """
        Return carrier data in format:
        {antenna: {tx: { state: , frequency: , type: , bandwidth: } } }

        :return: carrier data
        :rtype: dict
        """
        carrier_data_by_tx = self._parse_carrier_by_tx()
        carrier_data = {}
        for antena, tx_list in self._tx_per_antenna.items():
            tx_on_antena = {}
            for tx in tx_list:
                tx_on_antena.setdefault(tx, carrier_data_by_tx[tx])
            carrier_data.setdefault(antena, tx_on_antena)
        return carrier_data
